-- ============================================================================
-- PostgreSQL Data Dump & Schema for order_updates.csv
-- Engine: PostgreSQL 12+
-- ============================================================================

DROP TABLE IF EXISTS order_updates CASCADE;

CREATE TABLE order_updates (
    event_id         VARCHAR(64)  PRIMARY KEY,
    symbol           VARCHAR(32)  NOT NULL,
    transaction_type VARCHAR(4)   NOT NULL CHECK (transaction_type IN ('BUY', 'SELL')),
    quantity         INTEGER      NOT NULL CHECK (quantity > 0),
    created_at       TIMESTAMPTZ  DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_order_updates_symbol ON order_updates(symbol);

BEGIN;


COMMIT;

-- ====================================================================
-- PostgreSQL Net Position Query
-- ====================================================================
SELECT 
    symbol,
    SUM(
        CASE 
            WHEN transaction_type = 'BUY'  THEN quantity
            WHEN transaction_type = 'SELL' THEN -quantity
            ELSE 0
        END
    ) AS net_position,
    COUNT(*) AS total_events,
    SUM(CASE WHEN transaction_type = 'BUY'  THEN quantity ELSE 0 END) AS total_buy_qty,
    SUM(CASE WHEN transaction_type = 'SELL' THEN quantity ELSE 0 END) AS total_sell_qty
FROM order_updates
GROUP BY symbol
ORDER BY symbol ASC;
